html:
{%- set ex = exporter_profile() -%}
{%- set sup = supplier_profile(doc.supplier, doc.get("supplier_gstin")) -%}
{%- set sos = doc.items | map(attribute="sales_order") | select | unique | list -%}

<style>
  .print-format { margin-top: 6mm; margin-bottom: 8mm; margin-left: 12mm; margin-right: 12mm; }
  body { margin: 0 !important; }
  div.print-format { margin: 0 !important; padding: 0 !important; }
  .efx { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; color: #16181d; font-size: 10.5px; line-height: 1.4; }
  .efx .doc { border: 1.4px solid #16181d; }
  .efx .title { text-align: center; font-weight: 700; font-size: 14px; letter-spacing: .2em; text-transform: uppercase; padding: 7px 8px 6px; border-bottom: 1.4px solid #16181d; }
  .efx .title small { display: block; font-size: 8px; letter-spacing: .14em; font-weight: 500; color: #6b7280; margin-top: 2px; }
  .efx table { width: 100%; border-collapse: collapse; }
  .efx td, .efx th { vertical-align: top; }
  .efx .grid td { border: 0.7px solid #b9bec8; padding: 3px 9px; }
  .efx .grid td table td { padding-top: 0 !important; padding-bottom: 2px !important; line-height: 1.3 !important; }
  .efx .seam td { border-bottom: 1.4px solid #16181d; }
  .efx .lbl { font-size: 7.6px; text-transform: uppercase; letter-spacing: .06em; color: #8a909c; font-weight: 600; margin-bottom: 2px; display: block; }
  .efx b { font-weight: 700; }
  .efx .mono { font-family: 'SFMono-Regular', Menlo, Consolas, monospace; }
  .efx .muted { color: #6b7280; }
  .efx .addr { white-space: pre-wrap; }
  .efx table.lines th { background: #f3f4f6; border: 0.7px solid #b9bec8; border-top: 1.4px solid #16181d; border-bottom: 1.4px solid #16181d; font-size: 8px; text-transform: uppercase; letter-spacing: .05em; color: #3b4250; padding: 5px 7px; text-align: left; }
  .efx table.lines td { border: 0.7px solid #b9bec8; padding: 6px 7px; }
  .efx .r { text-align: right; } .efx .c { text-align: center; }
  .efx .batches { margin-top: 5px; font-size: 8.8px; color: #3b4250; }
  .efx .batches .bt { padding: 1px 0; }
  .efx table.lines tr.sub td { border-top: 0; border-bottom: 0.5px dashed #d4d8df; font-size: 9px; padding-top: 2px; padding-bottom: 2px; }
  .efx table.lines tfoot td { border: 0.7px solid #b9bec8; border-top: 1.4px solid #16181d; padding: 6px 7px; font-weight: 700; }
  .efx .gd { padding: 6px 9px; font-size: 9.6px; }
  .efx .gd b { letter-spacing: .02em; }
  .efx .words { font-size: 9.6px; padding: 6px 9px; }
  .efx .tot td { padding: 3px 9px; font-size: 10px; }
  .efx .tot .g td { font-weight: 700; font-size: 11.5px; border-top: 1.4px solid #16181d; }
  .efx .sigbox { height: 70px; position: relative; }
  .efx .sigline { position: absolute; bottom: 6px; left: 9px; right: 9px; border-top: 0.7px solid #16181d; padding-top: 3px; font-size: 8.4px; }
  .efx .logo { max-height: 38px; max-width: 168px; margin-bottom: 5px; display: block; }
  .efx table.lh { width: 100%; border-collapse: collapse; }
  .efx table.lh td { vertical-align: middle; padding: 0; }
  .efx table.lh td.lh-logo { width: 104px; }
  .efx table.lh td.lh-logo img { height: 46px; max-width: 100px; display: block; }
  .efx td.lh-id { text-align: center; }
  .efx td.lh-id .nm { font-size: 15px; font-weight: 700; color: #16181d; letter-spacing: .015em; }
  .efx td.lh-id .addr { font-size: 8.6px; color: #41485a; line-height: 1.62; margin-top: 2px; }
  .efx td.lh-certs { width: 166px; text-align: right; white-space: nowrap; }
  .efx td.lh-certs img { height: 38px; vertical-align: middle; }
  .efx .lh-rule img { width: 100%; height: 3px; display: block; margin: 8px 0 11px; }
</style>

<div class="efx">
  <table class="lh"><tr>
    <td class="lh-logo">{% if ex.logo %}<img src="{{ ex.logo | e }}">{% endif %}</td>
    <td class="lh-id">
      <div class="nm">{{ ex.company_name }}</div>
      {% if ex.letterhead_addr %}<div class="addr">{{ ex.letterhead_addr | e }}{% if ex.letterhead_contact %}<br>{{ ex.letterhead_contact | e }}{% endif %}</div>{% endif %}
    </td>
    <td class="lh-certs">{% if ex.cert_badges %}<img src="{{ ex.cert_badges | e }}">{% endif %}</td>
  </tr></table>
  {% if ex.gradient_rule %}<div class="lh-rule"><img src="{{ ex.gradient_rule | e }}"></div>{% else %}<div style="height:2px;background:#16181d;margin:8px 0 11px"></div>{% endif %}
<div class="doc">
  <div class="title">Purchase Order<small>{% if doc.get("merchanting_trade") %}Third-country / merchanting procurement{% elif doc.merchant_export_scheme %}Merchant export &mdash; concessional 0.1% IGST (Notification 41/2017-IGST(R)){% else %}Procurement order{% endif %}{% if doc.docstatus == 0 %} &middot; DRAFT{% endif %}</small></div>

  <table class="grid">
    <tr class="seam">
      <td style="width:50%">
        <span class="lbl">Buyer / Invoice to</span><b>{{ ex.company_name }}</b>
        {% if ex.address %}<div class="addr muted">{{ ex.address | e }}</div>{% endif %}
        <table style="width:100%;font-size:9px;line-height:1.45;margin-top:3px">
          {% if ex.gstin %}<tr><td class="muted" style="border:0;padding:0;width:74px">GSTIN/UIN</td><td style="border:0;padding:0"><span class="mono">{{ ex.gstin }}</span></td></tr>{% endif %}
          {% if ex.state_name %}<tr><td class="muted" style="border:0;padding:0">State</td><td style="border:0;padding:0">{{ ex.state_name }}{% if ex.state_code %}, Code: {{ ex.state_code }}{% endif %}</td></tr>{% endif %}
          {% if ex.pan %}<tr><td class="muted" style="border:0;padding:0">PAN</td><td style="border:0;padding:0"><span class="mono">{{ ex.pan }}</span></td></tr>{% endif %}
          {% if ex.cin %}<tr><td class="muted" style="border:0;padding:0">CIN</td><td style="border:0;padding:0"><span class="mono">{{ ex.cin }}</span></td></tr>{% endif %}
          {% if ex.iec %}<tr><td class="muted" style="border:0;padding:0">IEC</td><td style="border:0;padding:0"><span class="mono">{{ ex.iec }}</span></td></tr>{% endif %}
        </table>
        {% if ex.statutory_lines %}<div class="muted" style="font-size:8.6px;white-space:pre-wrap;margin-top:3px">{{ ex.statutory_lines | e }}</div>{% endif %}
      </td>
      <td>
        <span class="lbl">Supplier (Bill from)</span><b>{{ sup.name }}</b>
        {% if sup.address %}<div class="addr muted">{{ sup.address | e }}</div>{% endif %}
        <table style="width:100%;font-size:9px;line-height:1.45;margin-top:3px">
          {% if sup.gstin %}<tr><td class="muted" style="border:0;padding:0;width:74px">GSTIN/UIN</td><td style="border:0;padding:0"><span class="mono">{{ sup.gstin }}</span></td></tr>{% endif %}
          {% if sup.state_name %}<tr><td class="muted" style="border:0;padding:0">State</td><td style="border:0;padding:0">{{ sup.state_name }}{% if sup.state_code %}, Code: {{ sup.state_code }}{% endif %}</td></tr>{% endif %}
          {% if sup.pan %}<tr><td class="muted" style="border:0;padding:0">PAN</td><td style="border:0;padding:0"><span class="mono">{{ sup.pan }}</span></td></tr>{% endif %}
          {% if sup.contact_person or sup.mobile %}<tr><td class="muted" style="border:0;padding:0">Contact</td><td style="border:0;padding:0">{% if sup.contact_person %}{{ sup.contact_person }}{% endif %}{% if sup.mobile %}{% if sup.contact_person %} &middot; {% endif %}{{ sup.mobile }}{% endif %}</td></tr>{% endif %}
          {% if sup.email %}<tr><td class="muted" style="border:0;padding:0">E-mail</td><td style="border:0;padding:0">{{ sup.email }}</td></tr>{% endif %}
        </table>
      </td>
    </tr>
    <tr class="seam">
      <td><span class="lbl">PO no &amp; date</span><b class="mono">{{ doc.name }}</b> &middot; {{ frappe.utils.formatdate(doc.transaction_date, "dd MMM yyyy") }}{% if doc.schedule_date %} &nbsp; <span class="muted">Required by {{ frappe.utils.formatdate(doc.schedule_date, "dd MMM yyyy") }}</span>{% endif %}</td>
      <td><span class="lbl">Mode / terms of payment</span>{{ doc.get("payment_terms_narrative") or "As agreed" }}</td>
    </tr>
    <tr class="seam">
      <td><span class="lbl">Terms of delivery</span>{% if sos %}Drop-ship &mdash; deliver direct to the port of shipment.{% else %}As advised.{% endif %}</td>
      <td><span class="lbl">Destination</span>{{ doc.get("named_place") or "&mdash;" }}</td>
    </tr>
  </table>

  {% if doc.get("merchanting_trade") %}<div class="gd" style="border-bottom:1.4px solid #16181d"><b>GST treatment &mdash; Third-country / merchanting:</b> goods do not enter India; outside the purview of Indian GST.</div>
  {% elif doc.merchant_export_scheme %}<div class="gd" style="border-bottom:1.4px solid #16181d"><b>GST treatment &mdash; Merchant export:</b> supply at concessional 0.1% IGST under Notification 41/2017-IGST(R); goods are procured for export under LUT.</div>
  {% else %}<div class="gd" style="border-bottom:1.4px solid #16181d"><b>GST treatment &mdash; Standard domestic supply:</b> charge GST as applicable per the HSN.</div>{% endif %}

  <table class="lines">
    <thead><tr>
      <th style="width:18px">Sr</th>
      <th>Description of goods</th>
      <th style="width:92px">Packing required</th>
      <th style="width:68px">HSN/SAC</th>
      <th style="width:62px">Due on</th>
      <th class="r" style="width:70px">Qty</th>
      <th class="r" style="width:76px">Rate</th>
      <th class="r" style="width:90px">Amount ({{ doc.currency }})</th>
    </tr></thead>
    <tbody>
    {% for row in doc.items %}
      <tr>
        <td class="c mono">{{ loop.index }}</td>
        <td><b>{{ row.item_name }}</b>{% if row.item_code != row.item_name %} <span class="muted mono" style="font-size:8.4px">{{ row.item_code }}</span>{% endif %}{% if row.get("specification") %}<div class="muted" style="font-size:8.6px;white-space:pre-wrap;margin-top:1px"><b>Specification:</b> {{ row.specification }}</div>{% endif %}</td>
        <td style="font-size:8.8px;white-space:pre-wrap">{{ row.get("packaging") or "&mdash;" }}</td>
        <td class="mono">{{ row.get("gst_hsn_code") or "&mdash;" }}</td>
        <td>{% if row.get("schedule_date") %}{{ frappe.utils.formatdate(row.schedule_date, "dd MMM yyyy") }}{% else %}&mdash;{% endif %}</td>
        <td class="r mono">{{ frappe.utils.flt(row.qty) }} {{ row.uom or "" }}</td>
        <td class="r mono">{{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}</td>
        <td class="r mono">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>

  <table>
    <tr>
      <td style="width:58%;border-right:0.7px solid #b9bec8;vertical-align:bottom">
        <div class="words"><span class="lbl">Amount in words</span>{{ frappe.utils.money_in_words(doc.grand_total, doc.currency) }}</div>
      </td>
      <td>
        <table class="tot">
          <tr><td>Net total</td><td class="r mono">{{ frappe.utils.fmt_money(doc.net_total, currency=doc.currency) }}</td></tr>
          {% for tax in doc.taxes %}<tr><td>{{ tax.description }}{% if tax.rate %} @ {{ frappe.utils.flt(tax.rate) }}%{% endif %}</td><td class="r mono">{{ frappe.utils.fmt_money(tax.base_tax_amount_after_discount_amount or tax.tax_amount, currency=doc.currency) }}</td></tr>{% endfor %}
          <tr class="g"><td>Grand total</td><td class="r mono">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  {% if doc.terms %}<div class="gd" style="border-top:0.7px solid #b9bec8;white-space:pre-wrap;font-size:9.6px"><span class="lbl">Terms &amp; conditions{% if doc.tc_name %} &middot; {{ doc.tc_name }}{% endif %}</span>{{ doc.terms | striptags }}</div>{% endif %}

  <table class="grid" style="border-top:1.4px solid #16181d"><tr>
    <td style="width:58%"><span class="lbl">Registration</span>{% if ex.pan %}PAN <span class="mono">{{ ex.pan }}</span>{% endif %}{% if ex.cin %}{% if ex.pan %} &middot; {% endif %}CIN <span class="mono">{{ ex.cin }}</span>{% endif %}<div class="muted" style="font-size:8.4px;margin-top:4px">{% if ex.jurisdiction %}Subject to {{ ex.jurisdiction }} jurisdiction. {% endif %}This is a computer-generated document.</div></td>
    <td class="sigbox"><div class="muted" style="font-size:9px">For <b>{{ ex.company_name }}</b></div><div class="sigline">{% if ex.signatory_name %}{{ ex.signatory_name }}{% if ex.signatory_designation %} &middot; {{ ex.signatory_designation }}{% endif %} &mdash; {% endif %}Authorised signatory</div></td>
  </tr></table>

</div></div>
